            aOrbiterG = RotL64((aOrbiterG * 0x3F375610D675F2CFULL), 27U);
            //
            aOrbiterH = ((aOrbiterH + aOrbiterB) + 0x707E21E0FD4148D6ULL) + aTwistOrbiterUpdateSaltA[((aIndex + 23U)) & S_SALT1];
