            aOrbiterB = ((aWandererI + RotL64(aIngress, 51U)) + RotL64(aCarry, 41U)) + 0x505166BD72AF92D8ULL;
            aOrbiterC = (((aWandererE + RotL64(aCross, 5U)) + RotL64(aCarry, 5U)) + 0x0B2905ACA519AA66ULL) + aTwistOrbiterAssignSaltB[((aIndex + 20U)) & S_SALT1];
            aOrbiterF = ((aWandererC + RotL64(aPrevious, 29U)) + 0xB58ACAF22EC65CFBULL) + aTwistOrbiterAssignSaltD[((aIndex + 28U)) & S_SALT1];
            aOrbiterK = (aWandererA + RotL64(aIngress, 37U)) + 0xE8A5AAF218DFC9F3ULL;
