            //
            aOrbiterE = (aOrbiterE + aOrbiterB) + 0xA7E5EC32E4A2CD75ULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterE) ^ 0x690185DD8DA8951EULL;
            aOrbiterG = RotL64((aOrbiterG * 0x8F1EC285E6EF1435ULL), 29U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterD) + 0xCF4645F07A1D29EFULL;
