            aCross = (RotL64(aWoodLaneC[((S_BLOCK1 - aIndex + 4316U)) & S_BLOCK1], 19U) ^ RotL64(aWoodLaneD[((S_BLOCK1 - aIndex + 4154U)) & S_BLOCK1], 11U));
