            aOrbiterB = ((aWandererH + RotL64(aCross, 54U)) + 0x6F8D5576ADB95391ULL) + aTwistOrbiterAssignSaltB[((aIndex + 29U)) & S_SALT1];
            aOrbiterE = ((aWandererA + RotL64(aIngress, 43U)) + RotL64(aCarry, 57U)) + 0x9894ECA32781E5C9ULL;
            aOrbiterG = ((aWandererK + RotL64(aScatter, 27U)) + RotL64(aCarry, 43U)) + 0x4541884EBEBA03B3ULL;
            aOrbiterI = ((aWandererB + RotL64(aPrevious, 21U)) + RotL64(aCarry, 23U)) + 0xE60B6F7B975B5F2EULL;
            aOrbiterD = ((aWandererG + RotL64(aCross, 13U)) + 0x6C24A43CCABB396CULL) + aTwistOrbiterAssignSaltC[(((31U - aIndex) + 10U)) & S_SALT1];
            //
            aOrbiterK = (aOrbiterK + aOrbiterH) + 0x07A020D5283B9A29ULL;
