            aOrbiterB = RotL64((aOrbiterB * 0x655EBEC47A0577E3ULL), 29U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterB) + 0xDFD76F3E20CA2BB3ULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterE) ^ 0xF4912C29D7C80F76ULL;
            aOrbiterG = RotL64((aOrbiterG * 0x113E76F6BCDA19A9ULL), 11U);
            //
