            aOrbiterK = ((aOrbiterK ^ aOrbiterJ) ^ 0xE0251FBC8599BBACULL) ^ aKeyRotateAOrbiterUpdateSaltF[(((31U - aIndex) + 7U)) & S_SALT1];
