            aIngress ^= (RotL64(aSoilLaneB[((aIndex + 12428U)) & S_BLOCK1], 37U) ^ RotL64(aWoodLaneA[((aIndex + 12804U)) & S_BLOCK1], 57U));
            aIngress = TwistMix64::DiffuseC((aIngress ^ aKeyRotateADomainWordIngress));
