            aCross = (RotL64(aPoisonLaneA[((S_BLOCK1 - aIndex + 14175U)) & S_BLOCK1], 24U) ^ RotL64(aPoisonLaneD[((S_BLOCK1 - aIndex + 13023U)) & S_BLOCK1], 43U));
            aCross ^= (RotL64(aWaterLaneA[((S_BLOCK1 - aIndex + 16328U)) & S_BLOCK1], 11U) ^ RotL64(aHeartLaneD[((S_BLOCK1 - aIndex + 10996U)) & S_BLOCK1], 53U));
            aCross = TwistMix64::DiffuseA((aCross ^ aKeyRotateADomainWordCross));
            //
            aScatter = (RotL64(aPrevious, 23U) ^ RotL64(aCross, 11U)) + (RotL64(aIngress, 58U) ^ RotL64(aCarry, 39U));
            aScatter = TwistMix64::DiffuseA((aScatter ^ aKeyRotateADomainWordScatter));
            //
