            aOrbiterF = RotL64((aOrbiterF * 0x897A4B785B37E4D7ULL), 51U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterB) + 0x2A2954989F497D66ULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterA) ^ 0x2CD871CA861BAB93ULL;
            aOrbiterC = RotL64((aOrbiterC * 0x38F01116484606C9ULL), 39U);
