            aOrbiterF = ((aOrbiterF + aOrbiterG) + 0x49CE22A661760E08ULL) + aKeyRotateAOrbiterUpdateSaltE[(((31U - aIndex) + 3U)) & S_SALT1];
            aOrbiterH = ((aOrbiterH ^ aOrbiterF) ^ 0xB3DE76F746E9DFBCULL) ^ aKeyRotateAOrbiterUpdateSaltA[((aIndex + 7U)) & S_SALT1];
