            aIngress = (RotL64(aFuseLaneB[((aIndex + 22348U)) & S_BLOCK1], 43U) ^ RotL64(aWindLaneD[((aIndex + 16737U)) & S_BLOCK1], 35U));
            aIngress ^= (RotL64(aFireLaneA[((aIndex + 16448U)) & S_BLOCK1], 52U) ^ RotL64(aPoisonLaneD[((S_BLOCK1 - aIndex + 22344U)) & S_BLOCK1], 27U));
            aIngress = TwistMix64::DiffuseA((aIngress ^ aKeyRotateADomainWordIngress));
            //
            aCross = (RotL64(aFuseLaneA[((S_BLOCK1 - aIndex + 20456U)) & S_BLOCK1], 37U) ^ RotL64(aWindLaneB[((S_BLOCK1 - aIndex + 20400U)) & S_BLOCK1], 3U));
            aCross ^= (RotL64(aMagmaLaneC[((S_BLOCK1 - aIndex + 17033U)) & S_BLOCK1], 23U) ^ RotL64(aPoisonLaneC[((aIndex + 16553U)) & S_BLOCK1], 48U));
            aCross = TwistMix64::DiffuseB((aCross ^ aKeyRotateADomainWordCross));
            //
            aScatter = (RotL64(aIngress, 35U) ^ RotL64(aCross, 5U)) + (RotL64(aCarry, 18U) + RotL64(aPrevious, 51U));
            aScatter = TwistMix64::DiffuseB((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterA = ((aWandererD + RotL64(aScatter, 13U)) + 0x9F51BE2AEB8D0F25ULL) + aKeyRotateAOrbiterAssignSaltC[(((31U - aIndex) + 20U)) & S_SALT1];
            aOrbiterH = (((aWandererI + RotL64(aCross, 35U)) + RotL64(aCarry, 39U)) + 0x4DB890928196EB8DULL) + aKeyRotateAOrbiterAssignSaltB[(((31U - aIndex) + 7U)) & S_SALT1];
            aOrbiterB = (aWandererE + RotL64(aIngress, 24U)) + 0x0EF04442AD48F9F5ULL;
            aOrbiterC = (aWandererB + RotL64(aPrevious, 57U)) + 0xBCA097ADC7410364ULL;
            aOrbiterD = ((aWandererH + RotL64(aIngress, 47U)) + RotL64(aCarry, 13U)) + 0x1324AD22B049D030ULL;
            aOrbiterG = (aWandererA + RotL64(aScatter, 3U)) + 0xAD2C63AD372FAB26ULL;
            aOrbiterJ = ((aWandererK + RotL64(aPrevious, 41U)) + RotL64(aCarry, 57U)) + 0x68415C586928C7BDULL;
            //
            aOrbiterA = (aOrbiterA + aOrbiterH) + 0xF95C7DB0B946D934ULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterA) ^ 0xB8B4C4F2886AE3C0ULL;
            aOrbiterB = RotL64((aOrbiterB * 0xD789F9E25BED4657ULL), 21U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterD) + 0xA0AEBC7D25F51D79ULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterC) ^ 0xC914B41A7D7D4D71ULL;
            aOrbiterG = RotL64((aOrbiterG * 0x6BA51E8DAC3E5A8FULL), 29U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterA) + 0x863F31D78893DD74ULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterJ) ^ 0xADA72FD0D9BE5C73ULL;
            aOrbiterH = RotL64((aOrbiterH * 0x733B4B45120EA355ULL), 3U);
            //
            aOrbiterH = ((aOrbiterH + aOrbiterB) + 0xF2BD50A113E33C43ULL) + aKeyRotateAOrbiterUpdateSaltF[((aIndex + 23U)) & S_SALT1];
            aOrbiterC = ((aOrbiterC ^ aOrbiterH) ^ 0x47C3E37AE414BB66ULL) ^ aKeyRotateAOrbiterUpdateSaltD[(((31U - aIndex) + 27U)) & S_SALT1];
            aOrbiterC = RotL64((aOrbiterC * 0x7D7B176DA29E9DADULL), 47U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterJ) + 0x8B2AD399AAF059BDULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterG) ^ 0xF2AF219C5AA9328BULL;
            aOrbiterA = RotL64((aOrbiterA * 0xC1FC1013DB8AA091ULL), 37U);
            //
            aOrbiterD = ((aOrbiterD + aOrbiterG) + 0xFCDEEF8E1AB486D8ULL) + aKeyRotateAOrbiterUpdateSaltE[((aIndex + 15U)) & S_SALT1];
            aOrbiterJ = ((aOrbiterJ ^ aOrbiterD) ^ 0xBA9811994B05EC63ULL) ^ aKeyRotateAOrbiterUpdateSaltC[((aIndex + 4U)) & S_SALT1];
            aOrbiterJ = RotL64((aOrbiterJ * 0x3DCA7261EFCEBD55ULL), 13U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterC) + 0x10A1D9E88631F224ULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterB) ^ 0xD9AC561346287C12ULL;
            aOrbiterD = RotL64((aOrbiterD * 0x525B8F54B2245E7FULL), 53U);
            //
            aIngress = aOrbiterB ^ RotL64(aOrbiterH, 29U);
            aIngress = aIngress + (RotL64(aOrbiterG, 19U) ^ aOrbiterD);
            aIngress = aIngress + (RotL64(aOrbiterC, 3U) ^ aOrbiterJ);
            aIngress = aIngress + RotL64(aOrbiterA, 47U);
            aIngress = TwistMix64::DiffuseB((aIngress + aScatter));
            //
            aWandererI = aWandererI + ((RotL64(aCross, 21U) + aOrbiterG) + RotL64(aOrbiterC, 5U));
            aWandererE = aWandererE ^ ((RotL64(aScatter, 39U) + aOrbiterA) + RotL64(aOrbiterB, 57U));
            aWandererH = aWandererH + ((((RotL64(aPrevious, 48U) + aOrbiterD) + RotL64(aOrbiterB, 51U)) + RotL64(aCarry, 13U)) + aKeyRotateAWandererUpdateSaltB[((aIndex + 24U)) & S_SALT1]);
            aWandererD = aWandererD ^ ((RotL64(aIngress, 3U) + RotL64(aOrbiterC, 21U)) + aOrbiterA);
            aWandererB = aWandererB + (((RotL64(aScatter, 11U) + RotL64(aOrbiterH, 14U)) + aOrbiterJ) + RotL64(aCarry, 27U));
            aWandererA = aWandererA ^ ((RotL64(aIngress, 57U) + RotL64(aOrbiterD, 29U)) + aOrbiterG);
            aWandererK = aWandererK + (((RotL64(aCross, 27U) + aOrbiterH) + RotL64(aOrbiterA, 41U)) + aKeyRotateAWandererUpdateSaltE[((aIndex + 19U)) & S_SALT1]);
